PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, display_name TEXT, locale TEXT DEFAULT 'en', currency TEXT DEFAULT 'USD', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, bpm REAL DEFAULT 120, musical_key TEXT, sample_rate INTEGER DEFAULT 48000, bit_depth INTEGER DEFAULT 24, status TEXT DEFAULT 'active', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS tracks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, name TEXT NOT NULL, kind TEXT NOT NULL, gain REAL DEFAULT 0, pan REAL DEFAULT 0, muted INTEGER DEFAULT 0, solo INTEGER DEFAULT 0, armed INTEGER DEFAULT 0, position INTEGER DEFAULT 0, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS clips (id TEXT PRIMARY KEY, track_id TEXT NOT NULL, asset_url TEXT, start_time REAL NOT NULL, duration REAL NOT NULL, offset_time REAL DEFAULT 0, gain REAL DEFAULT 0, fade_in REAL DEFAULT 0, fade_out REAL DEFAULT 0, FOREIGN KEY(track_id) REFERENCES tracks(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS effects (id TEXT PRIMARY KEY, track_id TEXT, project_id TEXT, slot INTEGER NOT NULL, type TEXT NOT NULL, enabled INTEGER DEFAULT 1, params_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS automations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, parameter TEXT NOT NULL, points_json TEXT NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS versions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL, created_by TEXT NOT NULL, label TEXT, snapshot_json TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ai_jobs (id TEXT PRIMARY KEY, project_id TEXT, user_id TEXT NOT NULL, job_type TEXT NOT NULL, status TEXT DEFAULT 'queued', input_json TEXT NOT NULL DEFAULT '{}', output_json TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subscriptions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, plan TEXT NOT NULL, status TEXT NOT NULL, provider TEXT DEFAULT 'nnit_pay', external_id TEXT, current_period_end TEXT);
CREATE TABLE IF NOT EXISTS marketplace_items (id TEXT PRIMARY KEY, seller_id TEXT NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, price_minor INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT DEFAULT 'draft', metadata_json TEXT NOT NULL DEFAULT '{}');
